[InitializeOnLoad]public static class MotionActionChecks {
 const string Pending="MotionActionQA";static List<string> rows;static TrainingOverlay hud;static TrainingFighter f;static ArmoredStaticPoseView view;static TrainingApprovedCharacter original,fixture;static TrainingMotionAction idle,walk;static Keyboard keyboard;static InputSettings old,temp;static IDisposable profile;static int stage,count;static float start,x;static double deadline;static string report,originalBytes;
