 static string Arg(string key,string fallback){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,key);return i<0?fallback:a[i+1];}
 static void C(bool ok,string text){if(!ok)throw new Exception(text);rows.Add("PASS "+text);count++;}
 public static void Edit(){var c=AssetDatabase.LoadAssetAtPath<TrainingApprovedCharacter>("Assets/Shioka/調整Data/Fighter/Awari/Data/AwariCharacter.asset");string path="Assets/__MotionActionQA_"+Guid.NewGuid().ToString("N")+".asset";try{var saved=UnityEngine.Object.Instantiate(c.idleAction);AssetDatabase.CreateAsset(saved,path);var editor=(TrainingMotionActionEditor)Editor.CreateEditor(saved);editor.OpenScenePreview();if(!editor.ScenePreviewEnabled)throw new Exception("Scene preview creation");editor.StopScenePreview();if(editor.ScenePreviewEnabled)throw new Exception("Scene preview cleanup");UnityEngine.Object.DestroyImmediate(editor);var draft=UnityEngine.Object.Instantiate(saved);draft.poses[0].visualOffset=new Vector2(.1f,.2f);draft.poses=new[]{new TrainingMotionPose{sprite=c.IdleSprite,holdFrames=2},new TrainingMotionPose{sprite=c.ForwardSprite,holdFrames=3}};if(draft.Sample(1).sprite!=c.IdleSprite||draft.Sample(2).sprite!=c.ForwardSprite||draft.Sample(5).sprite!=c.IdleSprite)throw new Exception("Integer hold boundaries");draft.loop=false;if(draft.Sample(99).sprite!=c.ForwardSprite)throw new Exception("Clamped final pose");draft.poses[0].visualOffset=new Vector2(.1f,.2f);if(saved.poses[0].visualOffset!=Vector2.zero)throw new Exception("Draft mutated asset");TrainingMotionActionEditor.SaveDraft(saved,draft);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);if(AssetDatabase.LoadAssetAtPath<TrainingMotionAction>(path).poses[0].visualOffset!=new Vector2(.1f,.2f))throw new Exception("Save/reload");draft.poses[0].holdFrames=0;if(draft.Validate(out _))throw new Exception("Invalid hold accepted");try{TrainingMotionActionEditor.SaveDraft(saved,draft);throw new Exception("Invalid save accepted");}catch(ArgumentException){}File.WriteAllText(Arg("-motionEditReport","Temp/motion-edit.txt"),"PASS isolated draft, explicit same-asset save/reload, invalid save rejection; temporary QA asset removed");UnityEngine.Object.DestroyImmediate(draft);}finally{AssetDatabase.DeleteAsset(path);}}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");SessionState.SetBool(Pending,true);EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));InputSystem.Update();start=Time.fixedTime;}
 static bool Elapsed(int frames)=>(Time.fixedTime-start)/Time.fixedDeltaTime>=frames-.01f;
 static void Setup(){rows=new List<string>();report=Arg("-motionReport","Temp/motion-play.txt");deadline=EditorApplication.timeSinceStartup+90;hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();f=hud.player;view=f.GetComponent<ArmoredStaticPoseView>();original=view.characterProfile;originalBytes=File.ReadAllText(AssetDatabase.GetAssetPath(original));profile=KeyConfigService.UseForTests(KeyConfigService.Defaults(),new KeyConfigStore(Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".json")));hud.ReloadUserInput();old=InputSystem.settings;temp=UnityEngine.Object.Instantiate(old);temp.updateMode=InputSettings.UpdateMode.ProcessEventsManually;temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temp;keyboard=InputSystem.AddDevice<Keyboard>();C(original.idleAction!=null&&original.forwardWalkAction!=null&&original.idle==null&&original.forward==null,"individual assets are sole adopted Idle/Forward image sources");C(f.MotionPose.sprite==original.IdleSprite,"baseline Idle image");var b=f.GetComponent<TrainingMotor2D>();var h=f.Hurtboxes[0];C(Mathf.Abs(h.Collider.size.x-b.radius*2)<.0001f&&Mathf.Abs(h.Collider.size.y-b.height)<.0001f,"baseline effective hurt geometry unchanged");C(h.Region.selectionPriority==0&&h.Region.midDefense==100,"priority and defense unchanged");C(original.idleAction.poses[0].visualOffset==Vector2.zero,"baseline image position unchanged");fixture=UnityEngine.Object.Instantiate(original);idle=UnityEngine.Object.Instantiate(original.idleAction);walk=UnityEngine.Object.Instantiate(original.forwardWalkAction);fixture.idleAction=idle;fixture.forwardWalkAction=walk;idle.poses[0].sprite=original.ForwardSprite;idle.poses[0].visualOffset=new Vector2(.1f,.2f);idle.poses[0].hurt[0].center=new Vector2(.12f,.8f);idle.poses[0].hurt[0].size=new Vector2(.6f,1.4f);walk.poses[0].sprite=original.IdleSprite;walk.poses[0].visualOffset=new Vector2(.2f,.1f);walk.poses[0].hurt[0].center=new Vector2(.15f,.7f);walk.poses[0].hurt[0].size=new Vector2(.7f,1.3f);view.characterProfile=fixture;Keys();stage=1;}
 static void Tick(){try{if(!EditorApplication.isPlaying||Time.frameCount<5)return;if(rows==null){Setup();return;}InputSystem.Update();if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Bounded timeout");if(stage==1&&Elapsed(3)){C(view.image.sprite==original.ForwardSprite,"Idle asset sprite override reaches runtime");C(Vector3.Distance(view.image.transform.localPosition,new Vector3(.1f*f.Facing,.2f,0))<.0001f,"Idle offset reaches runtime with facing");C(f.Hurtboxes[0].Collider.size==new Vector2(.6f,1.4f),"Idle hurt override reaches runtime");x=f.transform.position.x;Keys(Key.D);stage=2;}else if(stage==2&&Elapsed(3)){C(f.MotionAction==walk&&view.image.sprite==original.IdleSprite,"ForwardWalk asset sprite reaches runtime");C(f.Hurtboxes[0].Collider.size==new Vector2(.7f,1.3f),"ForwardWalk hurt reaches runtime");C(f.transform.position.x>x&&Mathf.Abs(f.HorizontalVelocity)<=f.walkSpeed,"existing walking movement retained");Keys(Key.A);stage=3;}else if(stage==3&&Elapsed(12)){C(f.MotionAction==original.backwardWalkAction&&view.DisplayedState=="BackwardWalk","retreat restores existing behavior");Keys();stage=4;}else if(stage==4&&Elapsed(12)){C(f.MotionAction==idle,"release returns Idle asset");hud.Session.ResetConfigured();f.GetComponent<TrainingMotor2D>().Teleport(new Vector2(.8f,.01f));f.opponent.GetComponent<TrainingMotor2D>().Teleport(new Vector2(-.8f,.01f));f.RefreshTrainingFacing();Keys();stage=5;}else if(stage==5&&Elapsed(3)){C(f.Facing<0&&Mathf.Abs(f.Hurtboxes[0].Collider.offset.x+.12f)<.0001f,"mirrored Idle hurt offset");C(view.image.flipX&&Mathf.Abs(view.image.transform.localPosition.x+.1f)<.0001f,"mirrored Idle image");Keys(Key.A);stage=6;}else if(stage==6&&Elapsed(3)){C(f.MotionAction==walk&&Mathf.Abs(f.Hurtboxes[0].Collider.offset.x+.15f)<.0001f,"mirrored ForwardWalk shape");Keys(Key.W);stage=7;}else if(stage==7&&Elapsed(14)){C(f.MotionAction==original.jumpAction&&f.CurrentPhase==TrainingFighter.Phase.Air,"jump leaves motion overrides");Keys();stage=8;}else if(stage==8&&Elapsed(75)){C(f.IsGrounded&&f.MotionAction==idle,"landing restores Idle");fixture.idleAction=null;Keys();stage=9;}else if(stage==9&&Elapsed(2)){C(f.MotionPose==null&&f.Hurtboxes[0].Collider.size.y>1.5f,"null action restores baseline hurt fallback");view.characterProfile=original;Keys(Key.J);stage=10;}else if(stage==10&&Elapsed(2)){C(f.CurrentPhase==TrainingFighter.Phase.Attack&&f.MotionAction==null,"attack leaves motion overrides");C(File.ReadAllText(AssetDatabase.GetAssetPath(original))==originalBytes,"Play never saves authoring data");C(original.idleAction.poses[0].visualOffset==Vector2.zero,"fixture edits do not mutate adopted data");Finish(0);}}catch(Exception e){rows?.Add("FAIL "+e);Debug.LogException(e);Finish(1);}}
 static void Finish(int exit){SessionState.SetBool(Pending,false);EditorApplication.update-=Tick;if(view!=null)view.characterProfile=original;profile?.Dispose();if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(old!=null)InputSystem.settings=old;rows?.Add(count+" PASS; exit="+exit+"; virtual keyboard, not physical hardware");if(rows!=null)File.WriteAllLines(report,rows);EditorApplication.Exit(exit);}
